31	const PROCESSING_FEE = 5;
32	
33	// The MHPCO price list: one row per insurable item type.
34	type PriceListEntry = { insuranceValue: number; basePremium: number };
35	
36	const PRICE_LIST: Record<string, PriceListEntry> = {
37	  sword: { insuranceValue: 1000, basePremium: 100 },
38	  amulet: { insuranceValue: 600, basePremium: 60 },
39	  staff: { insuranceValue: 800, basePremium: 80 },
40	  potion: { insuranceValue: 400, basePremium: 40 },
41	  rune: { insuranceValue: 250, basePremium: 25 },
42	  moonstone: { insuranceValue: 250, basePremium: 25 },
43	};
44	
45	// MHPCO refuses business it cannot price or verify; every refusal is raised the same way.
46	const reject = (reason: string): never => {
47	  throw new Error(reason);
48	};
49	
50	// MHPCO only insures item types on its price list.
51	const priceListEntryOf = (item: Item): PriceListEntry =>
52	  PRICE_LIST[item.type] ?? reject(`Unknown item type: ${item.type}`);
53	
54	const CURSE_SURCHARGE_RATE = 0.5;
55	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
56	const HIGH_ENCHANTMENT_THRESHOLD = 5;
57	
58	const basePremiumOf = (item: Item): number => priceListEntryOf(item).basePremium;
59	
60	// An item without an explicit enchantment level counts as unenchanted.
61	const enchantmentOf = (item: Item): number => item.enchantment ?? 0;
62	
63	const isEnchantedAtLeast = (item: Item, threshold: number): boolean =>
64	  enchantmentOf(item) >= threshold;
65	
66	const curseSurchargeRateOf = (item: Item): number => (item.cursed ? CURSE_SURCHARGE_RATE : 0);
67	
68	const highEnchantmentSurchargeRateOf = (item: Item): number =>
69	  isEnchantedAtLeast(item, HIGH_ENCHANTMENT_THRESHOLD) ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0;
70	
71	const ITEM_SURCHARGE_RULES = [curseSurchargeRateOf, highEnchantmentSurchargeRateOf];
72	
73	const totalSurchargeRateOf = (item: Item): number =>
74	  ITEM_SURCHARGE_RULES.reduce((total, rateOf) => total + rateOf(item), 0);
75	
76	const premiumOf = (item: Item): number => basePremiumOf(item) * (1 + totalSurchargeRateOf(item));
77	
78	const BLOCK_SIZE = 3;
79	const PREMIUM_PER_BLOCK = 60;
80	
81	const groupByType = (items: Item[]): Item[][] => {
82	  const types = [...new Set(items.map((item) => item.type))];
83	  return types.map((type) => items.filter((item) => item.type === type));
84	};
85	
86	type ItemValuation = (item: Item) => number;
87	
88	const premiumOfSameTypeItems = (sameTypeItems: Item[], valueOf: ItemValuation): number =>
89	  sameTypeItems.length === BLOCK_SIZE
90	    ? PREMIUM_PER_BLOCK
91	    : sameTypeItems.reduce((sum, item) => sum + valueOf(item), 0);
92	
93	const blockPricedTotal = (items: Item[], valueOf: ItemValuation): number =>
94	  groupByType(items).reduce((total, group) => total + premiumOfSameTypeItems(group, valueOf), 0);
95	
96	const itemsPremiumWithSurcharges = (items: Item[]): number => blockPricedTotal(items, premiumOf);
97	
98	const itemsBasePremium = (items: Item[]): number => blockPricedTotal(items, basePremiumOf);
99	
100	type Customer = { yearsWithMHPCO: number };
101	
102	type PolicyContext = { customer: Customer; quotesSoFar: number };
103	
104	const LOYALTY_DISCOUNT_RATE = -0.2;
105	const LOYALTY_YEARS_THRESHOLD = 2;
106	
107	const loyaltyRateOf = ({ customer }: PolicyContext): number =>
108	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD ? LOYALTY_DISCOUNT_RATE : 0;
109	
110	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
111	
112	const firstInsuranceRateOf = (_context: PolicyContext): number => FIRST_INSURANCE_SURCHARGE_RATE;
113	
114	const FOLLOW_UP_DISCOUNT_RATE = -0.15;
115	
116	const followUpRateOf = ({ quotesSoFar }: PolicyContext): number =>
117	  quotesSoFar > 0 ? FOLLOW_UP_DISCOUNT_RATE : 0;
118	
119	const POLICY_RATE_RULES = [loyaltyRateOf, firstInsuranceRateOf, followUpRateOf];
120	
121	const totalPolicyRateOf = (context: PolicyContext): number =>
122	  POLICY_RATE_RULES.reduce((total, rateOf) => total + rateOf(context), 0);
123	
124	// MHPCO always rounds in its own favor: premiums it charges go up, payouts it owes go down.
125	const roundPremiumInMHPCOsFavor = (amount: number): number => Math.ceil(amount);
126	
127	const roundPayoutInMHPCOsFavor = (amount: number): number => Math.floor(amount);
128	
129	const premiumFor = (items: Item[], context: PolicyContext): number =>
130	  roundPremiumInMHPCOsFavor(
131	    itemsPremiumWithSurcharges(items) +
132	      itemsBasePremium(items) * totalPolicyRateOf(context) +
133	      PROCESSING_FEE,
134	  );
135	
136	const insuranceValueOf = (item: Item): number => priceListEntryOf(item).insuranceValue;
137	
138	const insuranceSumOf = (items: Item[]): number =>
139	  items.reduce((sum, item) => sum + insuranceValueOf(item), 0);
140	
141	const CAP_FACTOR = 2;
142	
143	const capOf = (items: Item[]): number => insuranceSumOf(items) * CAP_FACTOR;
144	
145	const DEDUCTIBLE = 100;
146	
147	const HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
148	const HALF_REIMBURSEMENT_RATE = 0.5;
149	
150	const FULL_REIMBURSEMENT_RATE = 1;
151	
152	const reimbursementRateOf = (insuredItem: Item): number =>
153	  isEnchantedAtLeast(insuredItem, HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD)
154	    ? HALF_REIMBURSEMENT_RATE
155	    : FULL_REIMBURSEMENT_RATE;
156	
157	const validatedAmountOf = (damage: Damage): number =>
158	  damage.amount < 0 ? reject(`Invalid damage amount: ${damage.amount}`) : damage.amount;
159	
160	const payoutForDamage = (damage: Damage, insuredItem: Item): number =>
161	  validatedAmountOf(damage) * reimbursementRateOf(insuredItem) - DEDUCTIBLE;
162	
163	const insuredItemFor = (damage: Damage, policyItems: Item[]): Item =>
164	  policyItems.find((item) => item.type === damage.itemType) ??
165	  reject(`Item not insured: ${damage.itemType}`);
166	
167	const countOfType = (itemType: string, items: { type: string }[]): number =>
168	  items.filter((item) => item.type === itemType).length;
169	
170	// A policy covers each insured item once: more damage entries of a type than
171	// insured items of that type means the claim is rejected.
172	const checkDamageCounts = (damages: Damage[], policyItems: Item[]): void => {
173	  damages.forEach((damage) => {
174	    if (
175	      countOfType(
176	        damage.itemType,
177	        damages.map((other) => ({ type: other.itemType })),
178	      ) > countOfType(damage.itemType, policyItems)
179	    ) {
180	      reject(`More ${damage.itemType} damages than insured: ${damage.itemType}`);
181	    }
182	  });
183	};
184	
185	const payoutForIncident = (incident: Incident, policyItems: Item[]): number => {
186	  checkDamageCounts(incident.damages, policyItems);
187	  return incident.damages.reduce(
188	    (total, damage) => total + payoutForDamage(damage, insuredItemFor(damage, policyItems)),
189	    0,
190	  );
191	};
192	
193	type ScenarioState = {
194	  context: PolicyContext;
195	  results: StepResult[];
196	  steps: Step[];
197	  remainingCaps: Record<number, number>;
198	};
199	
200	const policyItemsOf = (state: ScenarioState, step: ClaimStep): Item[] =>
201	  (state.steps[step.policy] as QuoteStep).items;
202	
203	// A policy starts out with its full cap and keeps whatever earlier claims left of it.
204	const remainingCapOf = (state: ScenarioState, step: ClaimStep): number =>
205	  state.remainingCaps[step.policy] ?? capOf(policyItemsOf(state, step));
206	
207	const claimResultFor = (state: ScenarioState, step: ClaimStep): ClaimResult => {
208	  const remainingCap = remainingCapOf(state, step);
209	  const desiredPayout = roundPayoutInMHPCOsFavor(
210	    payoutForIncident(step.incident, policyItemsOf(state, step)),
211	  );
212	  const payout = Math.min(desiredPayout, remainingCap);
213	  return { payout, remainingCap: remainingCap - payout };
214	};
215	
216	// What a step contributes to the scenario: its own result, plus whatever it
217	// used up of its policy's cap.
218	type StepOutcome = { result: StepResult; remainingCaps: Record<number, number> };
219	
220	const quoteOutcome = (state: ScenarioState, step: QuoteStep): StepOutcome => ({
221	  result: { premium: premiumFor(step.items, state.context) },
222	  remainingCaps: state.remainingCaps,
223	});
224	
225	const claimOutcome = (state: ScenarioState, step: ClaimStep): StepOutcome => {
226	  const result = claimResultFor(state, step);
227	  return {
228	    result,
229	    remainingCaps: { ...state.remainingCaps, [step.policy]: result.remainingCap },
230	  };
231	};
232	
233	const outcomeOf = (state: ScenarioState, step: Step): StepOutcome =>
234	  step.op === "quote" ? quoteOutcome(state, step) : claimOutcome(state, step);
235	
236	const applyStep = (state: ScenarioState, step: Step): ScenarioState => {
237	  const { result, remainingCaps } = outcomeOf(state, step);
238	  return {
239	    ...state,
240	    context: { ...state.context, quotesSoFar: state.context.quotesSoFar + 1 },
241	    results: [...state.results, result],
242	    remainingCaps,
243	  };
244	};
245	
246	export function runScenario(scenario: Scenario): ScenarioResult {
247	  const initialState: ScenarioState = {
248	    context: { customer: scenario.customer, quotesSoFar: 0 },
249	    results: [],
250	    steps: scenario.steps,
251	    remainingCaps: {},
252	  };
253	  return { results: scenario.steps.reduce(applyStep, initialState).results };
254	}
